"""Runtime path setup for bundled usd-convert-cad native dependencies."""

from __future__ import annotations

import os
import sys
from pathlib import Path
from types import ModuleType

_DLL_DIRECTORY_HANDLES: list[object] = []
_DLL_DIRECTORY_PATHS: set[str] = set()


def _same_path(left: Path, right: Path) -> bool:
    return os.path.normcase(str(left.resolve())) == os.path.normcase(str(right.resolve()))


def _is_relative_to(path: Path, parent: Path) -> bool:
    try:
        path.resolve().relative_to(parent.resolve())
        return True
    except ValueError:
        return False


def _module_path(module: ModuleType) -> Path | None:
    module_file = getattr(module, "__file__", None)
    if module_file:
        return Path(module_file)

    module_paths = getattr(module, "__path__", None)
    if module_paths:
        for module_path in module_paths:
            return Path(module_path)

    return None


def _check_pxr_conflict(vendored_usd_python_dir: Path) -> None:
    pxr_module = sys.modules.get("pxr")
    if pxr_module is None:
        return

    pxr_path = _module_path(pxr_module)
    if pxr_path is not None and _is_relative_to(pxr_path, vendored_usd_python_dir):
        return

    location = f" from {pxr_path}" if pxr_path is not None else ""
    raise RuntimeError(
        "usd-convert-cad requires its bundled pxr runtime, but pxr is already imported"
        f"{location}. Import usd_convert_cad before importing another OpenUSD distribution,"
        " or run the converter in a separate Python process."
    )


def _prepend_sys_path(path: Path) -> None:
    if any(_same_path(Path(entry), path) for entry in sys.path if entry):
        return

    sys.path.insert(0, str(path))


def _prepend_env_path(name: str, path: Path) -> None:
    path_str = str(path)
    paths = os.environ.get(name, "").split(os.pathsep) if os.environ.get(name) else []
    if not any(_same_path(Path(entry), path) for entry in paths if entry):
        os.environ[name] = os.pathsep.join([path_str, *paths])


def configure_runtime_paths() -> None:
    """Prepare bundled USD Python modules and native libraries for import."""
    package_dir = Path(__file__).resolve().parent
    vendored_usd_python_dir = package_dir / "_runtime"
    if (vendored_usd_python_dir / "pxr").is_dir():
        _check_pxr_conflict(vendored_usd_python_dir)
        _prepend_sys_path(vendored_usd_python_dir)

    hoops_dir = package_dir.parent / "omni" / "converter" / "hoops"
    if not hoops_dir.is_dir():
        return

    if os.name == "nt" and hasattr(os, "add_dll_directory"):
        hoops_dir_str = str(hoops_dir)
        if hoops_dir_str not in _DLL_DIRECTORY_PATHS:
            _DLL_DIRECTORY_HANDLES.append(os.add_dll_directory(hoops_dir_str))
            _DLL_DIRECTORY_PATHS.add(hoops_dir_str)

    _prepend_env_path("PATH" if os.name == "nt" else "LD_LIBRARY_PATH", hoops_dir)
    if os.name == "nt":
        _prepend_env_path("PXR_USD_WINDOWS_DLL_PATH", hoops_dir)

    usd_plugin_dir = hoops_dir / "usd"
    if usd_plugin_dir.is_dir():
        # Use a normal Python path so USD can expand the root plugInfo.json globs on Windows.
        _prepend_env_path("PXR_PLUGINPATH_NAME", usd_plugin_dir)
